ALTER TABLE public.student_profiles ADD COLUMN department_id uuid REFERENCES public.catalog_departments(id);
COMMENT ON COLUMN public.student_profiles.department_id IS 'Owning department; NULL is unassigned and must be reviewed by management.';
CREATE INDEX student_profiles_department_id_idx ON public.student_profiles(department_id);
UPDATE public.student_profiles sp SET department_id = d.id FROM public.catalog_departments d WHERE d.code = CASE WHEN sp.program_type = 'du_hoc' OR lower(coalesce(sp.program,'')) LIKE '%du học%' OR lower(coalesce(sp.program,'')) = 'du_hoc' THEN CASE WHEN lower(coalesce(sp.country,'')) IN ('duc','germany','ba-lan','hungary') THEN 'du_hoc_chau_au' WHEN lower(coalesce(sp.country,'')) IN ('nhat-ban','han-quoc') THEN 'du_hoc_nhat_han' ELSE NULL END ELSE CASE WHEN lower(coalesce(sp.country,'')) IN ('duc','germany','ba-lan','hungary') THEN 'tt_chau_au' WHEN lower(coalesce(sp.country,'')) = 'nhat-ban' THEN 'tt_nhat_ban' WHEN lower(coalesce(sp.country,'')) = 'han-quoc' THEN 'tt_han_quoc' WHEN lower(coalesce(sp.country,'')) = 'dai-loan' THEN 'tt_dai_loan' ELSE NULL END END;